        host.AttachMediaAsync(MediaSlot.Drive8, path, Arg.Any<bool>(), Arg.Any<CancellationToken>())
            .Returns(new ValueTask<AttachMediaResponse>(
                new AttachMediaResponse(RpcStatus.Ok(), Attachment(MediaSlot.Drive8, path))));

