    /// <summary>
    /// FEAT-XLOCALDEPLOY-001: builds the Xbox UWP head and refreshes the locally
    /// REGISTERED loose-file AppX layout in place, then relaunches the app - the
    /// session-proven dev loop as one command. Steps: stop a running instance (the
    /// copy would hit locked files), Restore+Build the head with the vswhere-located
    /// VS MSBuild (Restore heals the net10.0-fallback assets flip), robocopy the fresh
    /// output over Get-AppxPackage's InstallLocation (manifest excluded: the layout
    /// keeps its registered identity), and activate shell:AppsFolder. Prerequisite: a
    /// one-time VS deploy (F5) so the package IS registered; diagnostics land in
    /// LocalState\vicesharp.log.
    /// </summary>
    Target DeployXboxLocal => _ => _
        .Executes(() =>
        {
            if (!string.Equals(XboxDeployConfiguration, "Release-UWP", StringComparison.OrdinalIgnoreCase)
                && !string.Equals(XboxDeployConfiguration, "Debug-UWP", StringComparison.OrdinalIgnoreCase))
            {
                throw new InvalidOperationException(
                    $"--xbox-deploy-configuration '{XboxDeployConfiguration}' is not a UWP configuration (Release-UWP or Debug-UWP).");
            }

            // Windows PowerShell (5.1) hosts the Appx cmdlets natively; pwsh needs the
            // compatibility shim, so the loop shells the classic host deliberately.
            static string WinPs(string command)
            {
                var process = ProcessTasks.StartProcess(
                    "powershell.exe",
                    $"-NoProfile -NonInteractive -Command \"{command}\"",
                    logOutput: false);
                process.WaitForExit();
                return string.Join('\n', process.Output.Select(o => o.Text)).Trim();
            }

            const string packageName = "sharpninja.ViceSharp.Xbox";
            const string exeName = "ViceSharp.Xbox";

            // 1. Stop a running instance: robocopy onto a running app hits locked files.
            WinPs($"Stop-Process -Name '{exeName}' -Force -ErrorAction SilentlyContinue");

            // 2. Build the head on the proven toolchain. GenerateProjectPriFile is
            //    EXPLICIT: incremental Build does not refresh resources.pri, and UWP
            //    loads page XAML from the pri - without it a XAML-only change deploys
            //    STALE UI (operator 2026-07-14: "None of that is what I asked for";
            //    the restyled HomePage.xbf was fresh while the layout pri still served
            //    the previous menu). Restore is the /restore SWITCH, not an entry
            //    target: /t:Restore,X evaluates the project ONCE, and after a fallback
            //    (dotnet) restore the stale nuget.g.targets does not import the MSIX
            //    targets, so GenerateProjectPriFile does not exist yet (MSB4057).
            //    /restore restores and then RE-EVALUATES before building.
            var msbuild = ResolveVsMsBuild();
            var head = RootDirectory / "src" / "ViceSharp.Xbox" / "ViceSharp.Xbox.csproj";
            var build = ProcessTasks.StartProcess(
                msbuild,
                $"\"{head}\" /p:Configuration={XboxDeployConfiguration} /p:Platform=x64 /restore /t:Build,GenerateProjectPriFile /v:m /nologo",
                RootDirectory);
            build.WaitForExit();
            if (build.ExitCode != 0)
                throw new InvalidOperationException($"MSBuild failed with exit code {build.ExitCode}.");

            // 3. The registered layout is the deploy destination.
            var installLocation = WinPs($"(Get-AppxPackage -Name '{packageName}').InstallLocation");
            if (string.IsNullOrWhiteSpace(installLocation) || !Directory.Exists(installLocation))
            {
                throw new InvalidOperationException(
                    $"Package '{packageName}' is not registered (Get-AppxPackage returned nothing). " +
                    "Deploy once from Visual Studio (F5 with a UWP configuration) to register the loose-file layout, then rerun.");
            }

            var output = RootDirectory / "src" / "ViceSharp.Xbox" / "bin" / "x64" / XboxDeployConfiguration
                / "net10.0-windows10.0.26100.0" / "win-x64";
            if (!output.DirectoryExists())
                throw new InvalidOperationException($"Build output not found at '{output}'.");

            // 4. Refresh the layout in place (exit codes 0-7 are robocopy success).
            //    NO /XO: the timestamp filter skipped older-but-different files, so
            //    switching deploy configurations left a FRANKENBUILD layout (Release
            //    head over newer Debug core libs). The layout must deterministically
            //    mirror whatever was just built.
            var robocopy = ProcessTasks.StartProcess(
                "robocopy",
                $"\"{output}\" \"{installLocation}\" /S /XF AppxManifest.xml /XD AppX /NJH /NJS /NDL /NFL /NP",
                RootDirectory);
            robocopy.WaitForExit();
            if (robocopy.ExitCode > 7)
                throw new InvalidOperationException($"robocopy failed with exit code {robocopy.ExitCode}.");

            Serilog.Log.Information(
                "Deployed {Configuration} build into the registered layout: {Layout}",
                XboxDeployConfiguration, installLocation);

            // 5. Relaunch (opt-out via --xbox-launch false). Diagnostics:
            //    %LOCALAPPDATA%\Packages\<PFN>\LocalState\vicesharp.log
            if (XboxLaunch)
            {
                var familyName = WinPs($"(Get-AppxPackage -Name '{packageName}').PackageFamilyName");
                if (string.IsNullOrWhiteSpace(familyName))
                    throw new InvalidOperationException("Could not resolve the PackageFamilyName for launch.");

                WinPs($"Start-Process 'shell:AppsFolder\\{familyName}!App'");
                Serilog.Log.Information(
                    "Launched {Family}. Log: %LOCALAPPDATA%\\Packages\\{Family}\\LocalState\\vicesharp.log",
                    familyName, familyName);
            }
        });

    /// <summary>Locates the Visual Studio MSBuild (the proven UWP toolchain) via vswhere.</summary>
    static AbsolutePath ResolveVsMsBuild()
    {
        var vswhere = (AbsolutePath)Environment.GetFolderPath(Environment.SpecialFolder.ProgramFilesX86)
            / "Microsoft Visual Studio" / "Installer" / "vswhere.exe";
        if (!vswhere.FileExists())
            throw new InvalidOperationException($"vswhere.exe not found at '{vswhere}' (install Visual Studio).");

        var probe = ProcessTasks.StartProcess(
            vswhere,
            "-latest -requires Microsoft.Component.MSBuild -find MSBuild\\**\\Bin\\MSBuild.exe",
            logOutput: false);
        probe.WaitForExit();

        var msbuild = probe.Output.Select(o => o.Text).FirstOrDefault(l => !string.IsNullOrWhiteSpace(l));
        if (string.IsNullOrWhiteSpace(msbuild) || !File.Exists(msbuild))
            throw new InvalidOperationException("vswhere found no MSBuild with the required components.");

        return (AbsolutePath)msbuild;
    }

    /// <summary>
    /// FEAT-XSTOREPIPE-001: local Microsoft Store certification pre-flight. Runs the
    /// Windows App Certification Kit (appcert.exe) against the Xbox head's Store
    /// package and FAILS on any verdict other than PASS (verdict read from the report's
    /// OVERALL_RESULT). Optional by policy: Partner Center runs the authoritative
    /// certification on every upload; this target merely fails the same checks about an
    /// hour earlier. Constraints (per the WACK documentation): appcert.exe requires an
    /// ACTIVE USER SESSION (never Session0, so never a service-hosted agent) and admin
    /// rights; the pipeline exposes it behind the opt-in runWack parameter.
    /// </summary>
    Target ValidateStorePackage => _ => _
        .Executes(() =>
        {
            var package = ResolveStorePackage();
            Serilog.Log.Information("WACK input package: {Package}", package);

            // An .msixupload/.appxupload is a zip around the per-architecture package:
            // extract and validate the inner .msix/.appx (appcert tests packages, not uploads).
            var wackDirectory = ArtifactsDirectory / "wack";
            wackDirectory.CreateDirectory();

            var packagePath = package.ToString();
            AbsolutePath msix = package;
            if (packagePath.EndsWith(".msixupload", StringComparison.OrdinalIgnoreCase)
                || packagePath.EndsWith(".appxupload", StringComparison.OrdinalIgnoreCase))
            {
                var extractDirectory = wackDirectory / "extracted";
                extractDirectory.CreateOrCleanDirectory();
                ZipFile.ExtractToDirectory(packagePath, extractDirectory, overwriteFiles: true);
                msix = extractDirectory.GlobFiles("*.msix", "*.appx").FirstOrDefault()
                    ?? throw new InvalidOperationException(
                        $"The upload package '{package}' contains no .msix/.appx.");
                Serilog.Log.Information("Extracted inner package: {Msix}", msix);
            }

            var appcert = (AbsolutePath)Environment.GetFolderPath(Environment.SpecialFolder.ProgramFilesX86)
                / "Windows Kits" / "10" / "App Certification Kit" / "appcert.exe";
            if (!appcert.FileExists())
                throw new InvalidOperationException(
                    $"appcert.exe not found at '{appcert}'. Install the Windows App Certification Kit (ships with the Windows SDK).");

            var report = wackDirectory / $"wack-report-{DateTime.Now:yyyyMMdd-HHmmss}.xml";

            // reset clears prior kit state; it needs admin, and a failure here surfaces
            // again in the test run, so it is deliberately tolerant.
            ProcessTasks.StartProcess(appcert, "reset", RootDirectory).WaitForExit();

            var test = ProcessTasks.StartProcess(
                appcert,
                $"test -appxpackagepath \"{msix}\" -reportoutputpath \"{report}\"",
                RootDirectory);
            test.WaitForExit();

            if (!report.FileExists())
                throw new InvalidOperationException(
                    $"WACK produced no report (appcert exit {test.ExitCode}). appcert.exe requires an active user session (never Session0) and admin rights.");

            // The report is the verdict (appcert's exit code only says the run completed).
            var overall = XDocument.Load(report).Root?.Attribute("OVERALL_RESULT")?.Value ?? "UNKNOWN";
            Serilog.Log.Information("WACK OVERALL_RESULT={Result}; report: {Report}", overall, report);

            if (!string.Equals(overall, "PASS", StringComparison.OrdinalIgnoreCase))
                throw new InvalidOperationException(
                    $"WACK verdict '{overall}' (anything but PASS fails the pre-flight). Report: {report}");
        });

    /// <summary>
    /// Resolves the Store package for <see cref="ValidateStorePackage"/>: the explicit
    /// --store-package-path when given, else the newest upload package (or packaged
    /// .msix) under the Xbox head.
    /// </summary>
    AbsolutePath ResolveStorePackage()
    {
        if (!string.IsNullOrWhiteSpace(StorePackagePath))
        {
            var explicitPath = (AbsolutePath)Path.GetFullPath(StorePackagePath);
            if (!explicitPath.FileExists())
                throw new InvalidOperationException($"--store-package-path '{explicitPath}' does not exist.");
            return explicitPath;
        }

        var headDirectory = RootDirectory / "src" / "ViceSharp.Xbox";
        var newest = headDirectory
            .GlobFiles("**/*.msixupload", "**/*.appxupload", "AppPackages/**/*.msix")
            .OrderByDescending(file => File.GetLastWriteTimeUtc(file))
            .FirstOrDefault();

        return newest ?? throw new InvalidOperationException(
            "No Store package found under src/ViceSharp.Xbox. Build one (UapAppxPackageBuildMode=StoreUpload) or pass --store-package-path.");
    }

    /// <summary>
    /// Publish the ViceSharp.Avalonia desktop GUI as a self-contained
    /// Windows desktop application, then pack it into a per-machine MSI via
    /// the WixToolset.Sdk wixproj at installer/. The MSI lands at
    /// artifacts/installer/ViceSharp.msi with version <see cref="MsiVersion"/>.
    /// </summary>
    Target PublishMsi => _ => _
        .DependsOn(Restore)
        .Executes(() =>
        {
            var isDebugMsi = string.Equals(Configuration, "Debug", StringComparison.OrdinalIgnoreCase);
            // A Debug MSI runs the per-cycle emulator on unoptimized JIT code (~10x slower;
            // a deployed Debug build measured ~50% of real time on a machine whose Release
            // build sustains ~500%). Local builds default Configuration to Debug, so require
            // an explicit opt-in before packaging one.
            if (isDebugMsi && !ResolveAutoBoolean(MsiAllowDebug, false, nameof(MsiAllowDebug)))
                throw new InvalidOperationException(
                    "PublishMsi with Configuration=Debug produces an unoptimized emulator. " +
                    "Pass --configuration Release (recommended) or --msi-allow-debug true to package a Debug build deliberately.");
            var aotEnabled = ResolveAutoBoolean(MsiAotEnabled, false, nameof(MsiAotEnabled));
            var enableDebugGrpc = ResolveAutoBoolean(MsiEnableDebugGrpc, isDebugMsi, nameof(MsiEnableDebugGrpc));
            if (enableDebugGrpc)
            {
                if (string.IsNullOrWhiteSpace(MsiRemoteControlToken))
                    throw new InvalidOperationException("MsiRemoteControlToken must be non-empty when debug gRPC surfaces are enabled.");
                if (MsiRemoteControlToken.Contains(';', StringComparison.Ordinal))
                    throw new InvalidOperationException("MsiRemoteControlToken cannot contain ';' because WiX DefineConstants uses ';' separators.");
                if (MsiRemoteControlPort <= 0 || MsiRemoteControlPort > 65535)
                    throw new InvalidOperationException("MsiRemoteControlPort must be in the range 1..65535.");
            }

            // Step 1: self-contained publish of ViceSharp.Avalonia. The standard
            // MSI payload is ALWAYS ReadyToRun + single-file + trimmed JIT (fast
            // startup, one exe, no unoptimized-deploy surprises); --msi-aot-enabled
            // true switches to a native AOT publish instead (AOT is inherently a
            // fully-trimmed single native exe, and PublishReadyToRun/
            // PublishSingleFile do not apply to it).
            Serilog.Log.Information(
                "Publishing ViceSharp.Avalonia ({Configuration}, self-contained {Mode}, DebugGrpc={DebugGrpc}, {Rid}) -> {Out}",
                Configuration,
                aotEnabled ? "native AOT" : "ReadyToRun+single-file+trimmed JIT",
                enableDebugGrpc,
                MsiRuntimeIdentifier,
                AvaloniaPublishDir);
            DotNetPublish(s =>
            {
                s = s
                    .SetProject(AvaloniaProject)
                    .SetConfiguration(Configuration)
                    .SetRuntime(MsiRuntimeIdentifier)
                    // Stamp the GitVersion semver into the published assembly (AssemblyVersion,
                    // FileVersion, InformationalVersion) so the running app can show it in the
                    // window title. Without this the exe stays at the default 1.0.0 and every
                    // deployed build looks identical. Matches the MSI ProductVersion below.
                    .SetVersion(MsiVersion)
                    .SetSelfContained(true)
                    .SetProperty("ILLinkTreatWarningsAsErrors", "false")
                    .SetProperty("DebugType", isDebugMsi ? "portable" : "none")
                    .SetProperty("DebugSymbols", isDebugMsi ? "true" : "false")
                    .SetProperty("DocumentationFile", string.Empty)
                    .SetProperty("GenerateDocumentationFile", "false")
                    .SetProperty("CopyDocumentationFilesFromPackages", "false");

                return aotEnabled
                    ? s.SetProperty("PublishAot", "true")
                    : s
                        .SetProperty("PublishAot", "false")
                        .SetProperty("PublishTrimmed", "true")
                        .SetProperty("TrimMode", "partial")
                        .SetProperty("PublishReadyToRun", "true")
                        .SetProperty("PublishSingleFile", "true")
                        .SetProperty("IncludeNativeLibrariesForSelfExtract", "true");
            });

            var exePath = AvaloniaPublishDir / "ViceSharp.Avalonia.exe";
            if (!exePath.FileExists())
                throw new InvalidOperationException(
                    $"Expected Avalonia entry exe at {exePath} but it was not produced. PublishMsi cannot continue.");

            // Step 1b: prune oversized files we don't want in the MSI.
            // WiX 5's <Files Include="**"> harvest is all-or-nothing per
            // glob, so apply the exclusion here. The native PDBs are the
            // big ticket items (libSkiaSharp.pdb ~84 MB,
            // libHarfBuzzSharp.pdb ~21 MB) and end users never attach a
            // debugger from Program Files.
            string[] excludeGlobs = isDebugMsi
                ? ["**/*.xml", "**/*.dbg", "**/createdump.exe"]
                : ["**/*.pdb", "**/*.xml", "**/*.dbg", "**/createdump.exe"];
            long deletedBytes = 0;
            int deletedCount = 0;
            foreach (var glob in excludeGlobs)
            {
                foreach (var f in AvaloniaPublishDir.GlobFiles(glob))
                {
                    var size = new System.IO.FileInfo(f).Length;
                    f.DeleteFile();
                    deletedBytes += size;
                    deletedCount++;
                }
            }
            Serilog.Log.Information("Pruned {Count} debug/doc files from publish dir ({Bytes:N0} bytes / {Mb:F1} MB)",
                deletedCount, deletedBytes, deletedBytes / 1024.0 / 1024.0);

            // Step 2: build the WiX installer project.
            InstallerOutputDir.CreateOrCleanDirectory();
            Serilog.Log.Information(
                "Building installer wixproj with PublishedRoot={Root}, DebugGrpc={DebugGrpc}, RemoteControlPort={RemoteControlPort}",
                AvaloniaPublishDir,
                enableDebugGrpc,
                MsiRemoteControlPort);
            DotNetBuild(s => s
                .SetProjectFile(InstallerProject)
                .SetConfiguration(Configuration)
                .SetProperty("ProductVersion", MsiVersion)
                .SetProperty("PublishedRoot", AvaloniaPublishDir)
                .SetProperty("EnableDebugGrpc", enableDebugGrpc ? "true" : "false")
                .SetProperty("RemoteControlToken", enableDebugGrpc ? MsiRemoteControlToken : string.Empty)
                .SetProperty("RemoteControlPort", enableDebugGrpc ? MsiRemoteControlPort.ToString(System.Globalization.CultureInfo.InvariantCulture) : string.Empty));

            // Step 3: copy the produced MSI to artifacts/installer/.
            var built = (RootDirectory / "installer" / "bin" / "x64" / Configuration / "en-US")
                .GlobFiles("*.msi").FirstOrDefault();
            if (built is null || !built.FileExists())
                built = (RootDirectory / "installer" / "bin" / "x64" / Configuration)
                    .GlobFiles("*.msi").FirstOrDefault();
            if (built is null || !built.FileExists())
                throw new InvalidOperationException(
                    $"WiX did not produce an MSI under installer/bin/x64/{Configuration}. Check the wixproj build log.");

            built.CopyToDirectory(InstallerOutputDir, ExistsPolicy.FileOverwrite);
            var dest = InstallerOutputDir / built.Name;
            if (dest != MsiOutputPath)
                dest.Rename(MsiOutputPath.Name, ExistsPolicy.FileOverwrite);

            Serilog.Log.Information("MSI ready: {Path} ({Size:N0} bytes)", MsiOutputPath, new System.IO.FileInfo(MsiOutputPath).Length);
        });

    static bool ResolveAutoBoolean(string value, bool autoValue, string parameterName)
    {
        if (string.IsNullOrWhiteSpace(value) || string.Equals(value, "auto", StringComparison.OrdinalIgnoreCase))
            return autoValue;
        if (bool.TryParse(value, out var parsed))
            return parsed;
        if (value is "1" or "0")
            return value == "1";

        throw new InvalidOperationException($"{parameterName} must be auto, true, false, 1, or 0.");
    }

    /// <summary>
    /// Install the most recent PublishMsi output silently via msiexec.
    /// The per-machine MSI requires elevation; when the current process is
    /// not already running as Administrator the target self-elevates via
    /// `gsudo` (preferred) or `sudo` (PowerShell 7.5+ on Windows 11) so a
    /// plain `pwsh ./build.ps1 InstallMsi` works for the user with a
    /// single UAC prompt. Exit code 3010 (success-reboot-required) is
    /// treated as success.
    /// </summary>
    Target InstallMsi => _ => _
        .DependsOn(PublishMsi)
        .Executes(() =>
        {
            if (!MsiOutputPath.FileExists())
                throw new InvalidOperationException(
                    $"MSI not found at {MsiOutputPath}. Run PublishMsi first.");

            var logPath = InstallerOutputDir / "install.log";
            var msiArgs = $"/i \"{MsiOutputPath}\" /qn /norestart /log \"{logPath}\"";

            int exitCode;
            if (IsCurrentProcessElevated())
            {
                Serilog.Log.Information("Installing {Msi} via msiexec /qn (already elevated)", MsiOutputPath);
                exitCode = RunProcess("msiexec.exe", msiArgs, throwOnNonZero: false);
            }
            else
            {
                var elevator = FindOnPath("gsudo.exe") ?? FindOnPath("gsudo")
                            ?? FindOnPath("sudo.exe") ?? FindOnPath("sudo");
                if (elevator is null)
                    throw new InvalidOperationException(
                        "InstallMsi needs Administrator privileges to write Program Files but "
                      + "neither gsudo nor sudo was found on PATH. Either install gsudo "
                      + "(`winget install gerardog.gsudo`) or run this target from an already "
                      + "elevated PowerShell session.");

                Serilog.Log.Information(
                    "Installing {Msi} via {Elevator} -> msiexec /qn (will trigger UAC prompt)",
                    MsiOutputPath, System.IO.Path.GetFileName(elevator));
                var elevatedArgs = $"msiexec.exe {msiArgs}";
                exitCode = RunProcess(elevator, elevatedArgs, throwOnNonZero: false);
            }

            if (exitCode is not (0 or 3010))
                throw new InvalidOperationException(
                    $"msiexec exited with code {exitCode}. See {logPath} for details "
                  + "(MSI error 1925 = elevation required; 1603 = generic install failure; "
                  + "consult the log's last 'Error' line).");

            Serilog.Log.Information("InstallMsi complete (exit {ExitCode})", exitCode);
        });

    static bool IsCurrentProcessElevated()
    {
        if (!OperatingSystem.IsWindows())
            return true;  // non-Windows: leave it to the user; msiexec is a no-op anyway
        try
        {
            using var identity = System.Security.Principal.WindowsIdentity.GetCurrent();
            var principal = new System.Security.Principal.WindowsPrincipal(identity);
            return principal.IsInRole(System.Security.Principal.WindowsBuiltInRole.Administrator);
        }
        catch
        {
            return false;
        }
    }

    /// <summary>
    /// Generate winget manifests for the latest PublishMsi output and stage
    /// them under artifacts/winget/. The manifests follow the winget singleton
    /// schema 1.6 (Version + Installer + DefaultLocale). When
    /// `wingetcreate` is available on PATH the target also runs
    /// `wingetcreate submit` to open a PR against microsoft/winget-pkgs;
    /// otherwise the manifests are left in artifacts/winget/ for manual PR.
    /// </summary>
    Target PublishWinget => _ => _
        .DependsOn(PublishGitHubRelease)
        .Executes(() =>
        {
            var version = RequireReleaseTag(nameof(PublishWinget));

            WingetOutputDir.CreateOrCleanDirectory();

            // Hash the exact MSI attached to the GitHub release (WiX MSIs are not
            // byte-reproducible, so a rebuilt MSI would checksum differently than
            // the asset winget actually downloads and validates).
            var sha = Sha256Hex(AcquireMsi(version));
            Serilog.Log.Information("Released MSI SHA256: {Sha}", sha);

            var (publisher, identifier) = SplitWingetPackageId(WingetPackageId);
            var manifestsDir = WingetOutputDir / "manifests" / publisher.Substring(0, 1).ToLowerInvariant() / publisher / identifier / version;
            manifestsDir.CreateDirectory();

            // Version manifest (root).
            var versionYaml =
$@"# yaml-language-server: $schema=https://aka.ms/winget-manifest.version.1.6.0.schema.json
PackageIdentifier: {WingetPackageId}
PackageVersion: {version}
DefaultLocale: en-US
ManifestType: version
ManifestVersion: 1.6.0
";
            System.IO.File.WriteAllText(manifestsDir / $"{WingetPackageId}.yaml", versionYaml);

            // Installer manifest.
            var installerYaml =
$@"# yaml-language-server: $schema=https://aka.ms/winget-manifest.installer.1.6.0.schema.json
PackageIdentifier: {WingetPackageId}
PackageVersion: {version}
InstallerType: wix
Scope: machine
InstallModes:
  - silent
  - silentWithProgress
UpgradeBehavior: install
Installers:
  - Architecture: x64
    InstallerUrl: https://github.com/sharpninja/vice-sharp/releases/download/v{version}/ViceSharp.msi
    InstallerSha256: {sha}
    InstallerType: wix
ManifestType: installer
ManifestVersion: 1.6.0
";
            System.IO.File.WriteAllText(manifestsDir / $"{WingetPackageId}.installer.yaml", installerYaml);

            // Default locale manifest.
            var localeYaml =
$@"# yaml-language-server: $schema=https://aka.ms/winget-manifest.defaultLocale.1.6.0.schema.json
PackageIdentifier: {WingetPackageId}
PackageVersion: {version}
PackageLocale: en-US
Publisher: {publisher}
PackageName: ViceSharp
License: GPL-2.0-or-later
ShortDescription: VICE-compatible Commodore 64 emulator (Avalonia GUI).
Description: |
  ViceSharp is a .NET 10 Commodore 64 emulator with VICE compatibility.
  This package installs the ViceSharp Avalonia desktop GUI: a full host
  with monitor, drive / tape attach, debug stepping, snapshot, frame
  capture, and cycle-accurate VIC-II / SID / CIA emulation.
Moniker: vicesharp
Tags:
  - commodore
  - c64
  - emulator
  - vice
PublisherUrl: https://github.com/sharpninja
PackageUrl: https://github.com/sharpninja/vice-sharp
ManifestType: defaultLocale
ManifestVersion: 1.6.0
";
            System.IO.File.WriteAllText(manifestsDir / $"{WingetPackageId}.locale.en-US.yaml", localeYaml);

            Serilog.Log.Information("Winget manifests staged at {Dir}", manifestsDir);

            // Submit the manifests as a PR to microsoft/winget-pkgs. Install the
            // Microsoft.WingetCreate .NET tool if it is not already on PATH, and
            // authenticate with WINGET_PAT or, failing that, the release agent's
            // gh CLI token.
            var wingetcreate = FindOnPath("wingetcreate.exe") ?? FindOnPath("wingetcreate");
            if (wingetcreate is null && !PublishDryRun)
            {
                // wingetcreate is NOT a dotnet global tool (not on nuget.org); it
                // ships as a standalone exe. Use the CURRENT build - the
                // /self-contained aka.ms link is stale at 1.0.4.0, while
                // /latest serves the current framework-dependent build.
                Serilog.Log.Information("wingetcreate not found; downloading the current standalone build.");
                var exe = TemporaryDirectory / "wingetcreate.exe";
                using (var http = new System.Net.Http.HttpClient { Timeout = TimeSpan.FromMinutes(5) })
                {
                    var bytes = http.GetByteArrayAsync("https://aka.ms/wingetcreate/latest").GetAwaiter().GetResult();
                    System.IO.File.WriteAllBytes(exe, bytes);
                }
                wingetcreate = exe.FileExists() ? exe.ToString() : null;
                // The current build is framework-dependent and targets an older
                // .NET; roll forward to whatever runtime the agent has installed.
                Environment.SetEnvironmentVariable("DOTNET_ROLL_FORWARD", "LatestMajor");
            }

            // Token sources, in order: WINGET_PAT, then GITHUB_TOKEN (the
            // machine-env convention, like NUGET_API_KEY), then the gh CLI. The
            // gh subprocess capture is the least reliable, so the env vars win.
            var token = Environment.GetEnvironmentVariable("WINGET_PAT");
            if (string.IsNullOrEmpty(token))
                token = Environment.GetEnvironmentVariable("GITHUB_TOKEN");
            if (string.IsNullOrEmpty(token))
            {
                var gh = FindOnPath("gh.exe") ?? FindOnPath("gh");
                if (gh is not null)
                    token = ProcessTasks.StartProcess(gh, "auth token", RootDirectory, logOutput: false)
                        .Output.Select(o => o.Text.Trim()).FirstOrDefault(t => t.Length > 0);
            }

            // New-vs-update: a package already in winget-pkgs gets a canonical
            // `update` (bumps only version + installer, preserving maintainer
            // locale edits); a new one gets a first-time `submit` of the
            // freshly-authored complete manifests.
            var exists = WingetPackageExists(WingetPackageId);
            var wingetCmd = exists
                ? $"update {WingetPackageId} --version {version} --urls \"{ReleaseMsiUrl(version)}\" --submit"
                : $"submit \"{manifestsDir}\"";
            var mode = exists ? "update" : "first-time submit";

            if (PublishDryRun)
                Serilog.Log.Information("[dry-run] {Id} -> {Mode}; would run: wingetcreate {Cmd}", WingetPackageId, mode, wingetCmd);
            else if (wingetcreate is null)
                Serilog.Log.Warning("wingetcreate unavailable; manifests left in {Dir} for a manual winget-pkgs PR.", manifestsDir);
            else if (string.IsNullOrEmpty(token))
                Serilog.Log.Warning("No WINGET_PAT and no gh token; manifests staged at {Dir} but NOT submitted.", manifestsDir);
            else
            {
                Serilog.Log.Information("{Id} -> {Mode}.", WingetPackageId, mode);
                RunProcess(wingetcreate, $"{wingetCmd} --token {token}", throwOnNonZero: true);
            }
        });

    /// <summary>
    /// True when the package already exists in microsoft/winget-pkgs, so a
    /// release should submit a version UPDATE rather than create a first-time
    /// NEW package. Probes the manifests folder through the GitHub contents API
    /// with the agent's gh CLI (no winget client needed on the agent). Falls
    /// back to false (first-time submit) when gh is unavailable - a plain submit
    /// also creates a new package, so this only affects new-vs-update wording.
    /// </summary>
    bool WingetPackageExists(string packageId)
    {
        var gh = FindOnPath("gh.exe") ?? FindOnPath("gh");
        if (gh is null) return false;
        var (publisher, identifier) = SplitWingetPackageId(packageId);
        var path = $"manifests/{publisher.Substring(0, 1).ToLowerInvariant()}/{publisher}/{identifier}";
        // A 404 here just means the package is not published yet (first-time),
        // so keep gh's "Not Found" off the warning stream.
        var exit = RunProcess(gh, $"api repos/microsoft/winget-pkgs/contents/{path} --silent", throwOnNonZero: false, logErrors: false);
        Serilog.Log.Information("winget-pkgs {Path} -> {Result}.", path, exit == 0 ? "exists (update)" : "not found (first-time)");
        return exit == 0;
    }

    static (string publisher, string identifier) SplitWingetPackageId(string id)
    {
        var parts = id.Split('.', 2);
        return parts.Length == 2 ? (parts[0], parts[1]) : (id, id);
    }

    static string? FindOnPath(string name)
    {
        var path = Environment.GetEnvironmentVariable("PATH") ?? string.Empty;
        foreach (var dir in path.Split(System.IO.Path.PathSeparator))
        {
            if (string.IsNullOrWhiteSpace(dir)) continue;
            try
            {
                var candidate = System.IO.Path.Combine(dir, name);
                if (System.IO.File.Exists(candidate)) return candidate;
            }
            catch { }
        }
        return null;
    }

    // logErrors=false routes stderr to debug instead of warning - use it for
    // probes where a non-zero exit is an expected answer (e.g. a 404 meaning
    // "not found"), so the output does not read as a failure.
    static int RunProcess(string fileName, string args, bool throwOnNonZero, bool logErrors = true)
    {
        var psi = new System.Diagnostics.ProcessStartInfo(fileName, args)
        {
            UseShellExecute = false,
            RedirectStandardOutput = true,
            RedirectStandardError = true,
        };
        using var p = System.Diagnostics.Process.Start(psi)!;
        p.OutputDataReceived += (_, e) => { if (e.Data != null) Serilog.Log.Information(e.Data); };
        p.ErrorDataReceived  += (_, e) => { if (e.Data != null) { if (logErrors) Serilog.Log.Warning(e.Data); else Serilog.Log.Debug(e.Data); } };
        p.BeginOutputReadLine();
        p.BeginErrorReadLine();
        p.WaitForExit();
        if (throwOnNonZero && p.ExitCode != 0)
            throw new InvalidOperationException($"{System.IO.Path.GetFileName(fileName)} exited with code {p.ExitCode}.");
        return p.ExitCode;
    }

    // Like RunProcess but also returns the combined stdout+stderr so the caller
    // can classify a non-zero exit (never throws on exit code).
    static (int ExitCode, string Output) RunProcessCapture(string fileName, string args)
    {
        var psi = new System.Diagnostics.ProcessStartInfo(fileName, args)
        {
            UseShellExecute = false,
            RedirectStandardOutput = true,
            RedirectStandardError = true,
        };
        var sb = new System.Text.StringBuilder();
        using var p = System.Diagnostics.Process.Start(psi)!;
        p.OutputDataReceived += (_, e) => { if (e.Data != null) { Serilog.Log.Information(e.Data); lock (sb) sb.AppendLine(e.Data); } };
        p.ErrorDataReceived  += (_, e) => { if (e.Data != null) { Serilog.Log.Warning(e.Data); lock (sb) sb.AppendLine(e.Data); } };
        p.BeginOutputReadLine();
        p.BeginErrorReadLine();
        p.WaitForExit();
        return (p.ExitCode, sb.ToString());
    }

    // True when a failed `choco push` was rejected for a reason a retry cannot
    // fix without moderator action: a 403 (a new version of a brand-new package
    // still pending moderation) or a 409 / duplicate (that version already
    // pushed). These are external policy states, not build defects.
    static bool IsChocoModerationRejection(string output)
    {
        if (string.IsNullOrEmpty(output))
            return false;

        string[] markers =
        {
            "Forbidden",
            "Conflict",
            "already been listed",
            "already exists",
            "A package version already exists",
        };
        return markers.Any(m => output.Contains(m, StringComparison.OrdinalIgnoreCase));
    }

    // ---- Package-manager publishing (winget / chocolatey / scoop) -----------
    // All three key off the single GitHub release MSI asset. WiX MSIs are NOT
    // byte-reproducible (per-build package code), so a checksum MUST be taken
    // over the exact released asset, never a locally rebuilt MSI. Hence these
    // targets DependsOn(PublishGitHubRelease) and download the released MSI.

    string ReleaseMsiUrl(string version) =>
        $"https://github.com/{GitHubRepo}/releases/download/v{version}/ViceSharp.msi";

    /// <summary>Download the MSI attached to the GitHub release for <paramref name="version"/> and return its local path.</summary>
    AbsolutePath DownloadReleasedMsi(string version)
    {
        var url = ReleaseMsiUrl(version);
        var dest = TemporaryDirectory / "ViceSharp.released.msi";
        Serilog.Log.Information("Downloading released MSI: {Url}", url);
        using var http = new System.Net.Http.HttpClient { Timeout = TimeSpan.FromMinutes(5) };
        http.DefaultRequestHeaders.UserAgent.ParseAdd("ViceSharp-build");
        // Retry: the asset URL can 404 for a few seconds right after the release
        // is published (propagation).
        Exception? last = null;
        for (var attempt = 1; attempt <= 5; attempt++)
        {
            try
            {
                var bytes = http.GetByteArrayAsync(url).GetAwaiter().GetResult();
                System.IO.File.WriteAllBytes(dest, bytes);
                Serilog.Log.Information("Downloaded {Bytes:N0} bytes.", bytes.Length);
                return dest;
            }
            catch (Exception ex)
            {
                last = ex;
                Serilog.Log.Warning("MSI download attempt {Attempt}/5 failed: {Message}", attempt, ex.Message);
                System.Threading.Thread.Sleep(TimeSpan.FromSeconds(5));
            }
        }
        throw new InvalidOperationException($"Failed to download the released MSI from {url} after 5 attempts.", last);
    }

    static string Sha256Hex(AbsolutePath file)
    {
        using var stream = System.IO.File.OpenRead(file);
        using var sha = System.Security.Cryptography.SHA256.Create();
        return Convert.ToHexString(sha.ComputeHash(stream));
    }

    [Parameter("Dry-run every publish target: do the local work (pack/build/hash/manifest) but skip every outward action (git tag push, GitHub release, nuget.org push, winget/choco/scoop submit) and log what would run.")]
    readonly bool PublishDryRun = false;

    /// <summary>Build the MSI locally via a nested Nuke invocation, stamped with the tag version.</summary>
    void BuildMsiLocally(string version)
    {
        if (!OperatingSystem.IsWindows())
            throw new InvalidOperationException("MSI packaging requires Windows.");
        // Interpolate the path's .ToString(); a bare string + AbsolutePath
        // concatenation resolves through AbsolutePath and throws (not rooted).
        var buildPs1 = (RootDirectory / "build.ps1").ToString();
        RunProcess("pwsh.exe",
            $"-NoProfile -NonInteractive -ExecutionPolicy Bypass -File \"{buildPs1}\" PublishMsi --configuration Release --msi-version-override {version}",
            throwOnNonZero: true);
        Assert.FileExists(MsiOutputPath);
    }

    /// <summary>
    /// The MSI to hash for a package-manager manifest: the released asset in a
    /// real run; the locally built MSI in a dry-run (no release exists to
    /// download from, so build it once and reuse it).
    /// </summary>
    AbsolutePath AcquireMsi(string version)
    {
        if (!PublishDryRun)
            return DownloadReleasedMsi(version);
        if (!MsiOutputPath.FileExists())
            BuildMsiLocally(version);
        Serilog.Log.Information("[dry-run] hashing the locally built MSI {Msi}.", MsiOutputPath);
        return MsiOutputPath;
    }

    AbsolutePath ChocolateySourceDir => RootDirectory / "packaging" / "chocolatey";
    AbsolutePath ChocolateyOutputDir => ArtifactsDirectory / "chocolatey";

    /// <summary>
    /// Build + push the Chocolatey package for the HEAD vX.Y.Z tag: stage the
    /// nuspec + tools, inject the released MSI URL + SHA256 into
    /// chocolateyinstall.ps1, `choco pack`, then `choco push` to
    /// community.chocolatey.org (subject to community moderation). The push is
    /// skipped - package left under artifacts/chocolatey - when ChocoApiKey or
    /// choco itself is unavailable.
    /// </summary>
    Target PublishChocolatey => _ => _
        .DependsOn(PublishGitHubRelease)
        .Executes(() =>
        {
            var version = RequireReleaseTag(nameof(PublishChocolatey));

            var choco = FindOnPath("choco.exe") ?? FindOnPath("choco");
            if (choco is null)
            {
                Serilog.Log.Warning("choco not on PATH; skipping the Chocolatey package.");
                return;
            }

            var url = ReleaseMsiUrl(version);
            var sha = Sha256Hex(AcquireMsi(version));

            // Stage a copy of the package and inject the url + checksum into the
            // install script (the source stays a token template).
            var stage = ChocolateyOutputDir / "pkg";
            stage.CreateOrCleanDirectory();
            (stage / "tools").CreateDirectory();
            System.IO.File.Copy(ChocolateySourceDir / "vice-sharp.nuspec", stage / "vice-sharp.nuspec", overwrite: true);
            System.IO.File.Copy(ChocolateySourceDir / "tools" / "chocolateyuninstall.ps1", stage / "tools" / "chocolateyuninstall.ps1", overwrite: true);
            var install = System.IO.File.ReadAllText(ChocolateySourceDir / "tools" / "chocolateyinstall.ps1")
                .Replace("__URL__", url)
                .Replace("__SHA256__", sha);
            System.IO.File.WriteAllText(stage / "tools" / "chocolateyinstall.ps1", install);

            RunProcess(choco,
                $"pack \"{stage / "vice-sharp.nuspec"}\" --version {version} --outputdirectory \"{ChocolateyOutputDir}\"",
                throwOnNonZero: true);

            var nupkg = ChocolateyOutputDir.GlobFiles($"vice-sharp.{version}.nupkg").FirstOrDefault()
                ?? throw new InvalidOperationException($"choco pack did not produce vice-sharp.{version}.nupkg.");

            if (PublishDryRun)
            {
                Serilog.Log.Information("[dry-run] packed {Nupkg}; would push it to chocolatey.org.", nupkg);
                return;
            }

            // Secrets reach the self-hosted release agent through its machine
            // environment (the same way PublishNuget reads NUGET_API_KEY).
            var chocoApiKey = Environment.GetEnvironmentVariable("CHOCO_API_KEY");
            if (string.IsNullOrWhiteSpace(chocoApiKey))
            {
                Serilog.Log.Warning("CHOCO_API_KEY not set; packed {Nupkg} but NOT pushing to chocolatey.org.", nupkg);
                return;
            }

            var (pushExit, pushOutput) = RunProcessCapture(choco,
                $"push \"{nupkg}\" --source https://push.chocolatey.org/ --api-key {chocoApiKey}");
            if (pushExit == 0)
            {
                Serilog.Log.Information("Pushed {Nupkg} to chocolatey.org (pending community moderation).", nupkg);
                return;
            }

            // chocolatey.org rejects a new version of a brand-new, not-yet-approved
            // package while a prior version is still in the moderation queue (403
            // Forbidden), and rejects an exact duplicate version (409 Conflict).
            // Neither is a build defect and a retry cannot help until moderation
            // clears, so warn and let the rest of the release stand rather than
            // reddening an otherwise-successful publish.
            if (IsChocoModerationRejection(pushOutput))
            {
                Serilog.Log.Warning(
                    "chocolatey.org rejected the push for {Nupkg} (moderation/duplicate; choco exit {Exit}). "
                    + "Package NOT updated - re-push once the pending version clears moderation.",
                    nupkg, pushExit);
                return;
            }

            throw new InvalidOperationException($"choco push failed with exit code {pushExit}.");
        });

    AbsolutePath ScoopManifestPath => RootDirectory / "bucket" / "vice-sharp.json";

    /// <summary>
    /// Update the in-repo Scoop manifest (bucket/vice-sharp.json) for the HEAD
    /// vX.Y.Z tag - version, released MSI URL, and SHA256 (lowercase hex) - and
    /// push it to the GitHub mirror's default branch (authenticated via gh's
    /// credential helper) so `scoop update` sees the new version. Users add the
    /// bucket with:
    ///   scoop bucket add vicesharp https://github.com/sharpninja/vice-sharp
    /// The commit is based on the mirror's current main (not the detached tag
    /// checkout), so it lands as a normal main commit.
    /// </summary>
    Target PublishScoop => _ => _
        .DependsOn(PublishGitHubRelease)
        .Executes(() =>
        {
            var version = RequireReleaseTag(nameof(PublishScoop));

            var url = ReleaseMsiUrl(version);
            var sha = Sha256Hex(AcquireMsi(version)).ToLowerInvariant();
            var repoUrl = $"https://github.com/{GitHubRepo}.git";

            if (PublishDryRun)
            {
                // Do not touch the working tree (no fetch/checkout) in a dry-run.
                Serilog.Log.Information(
                    "[dry-run] would set bucket/vice-sharp.json version={Version} url={Url} hash={Sha} and push it to {Repo} main.",
                    version, url, sha, repoUrl);
                return;
            }

            // Base the manifest change on the mirror's current main so it lands
            // as a clean main commit (the pipeline runs on a detached tag).
            RunProcess("git", $"fetch --depth 1 {repoUrl} main", throwOnNonZero: true);
            RunProcess("git", "checkout -B scoop-publish FETCH_HEAD", throwOnNonZero: true);

            var json = System.Text.Json.Nodes.JsonNode.Parse(System.IO.File.ReadAllText(ScoopManifestPath))!;
            json["version"] = version;
            json["architecture"]!["64bit"]!["url"] = url;
            json["architecture"]!["64bit"]!["hash"] = sha;
            var opts = new System.Text.Json.JsonSerializerOptions { WriteIndented = true };
            System.IO.File.WriteAllText(ScoopManifestPath, json.ToJsonString(opts) + "\n");

            RunProcess("git", $"add \"{ScoopManifestPath}\"", throwOnNonZero: true);
            RunProcess("git",
                $"-c user.email=ci@vicesharp -c user.name=\"ViceSharp CI\" commit -m \"chore(scoop): vice-sharp {version}\"",
                throwOnNonZero: false); // no-op if the manifest is unchanged
            RunProcess("git",
                $"-c credential.helper= -c credential.helper=\"!gh auth git-credential\" push {repoUrl} HEAD:main",
                throwOnNonZero: true);
            Serilog.Log.Information("Scoop manifest for {Version} pushed to the mirror's main.", version);
        });

    // ---- Xbox (UWP-on-console) head: PLAN-XBOXUWP S33 (IMPL-XBOXUWP-033) --------
    // Three targets for the ViceSharp.Xbox head, split by where they can run:
    //  - PublishXbox / DeployXbox: DEV-PC / MANUAL DEVICE targets. They need the
    //    windows-app / UWP workload and (for deploy) a paired Dev-Mode console, so
    //    they are NEVER wired into a CI/release pipeline. XboxCiConfigTests guards
    //    their absence from azure-pipelines.{ci,release}.yml.
    //  - ValidateXbox: the OFF-CONSOLE, workload-free gate. It runs on a plain
    //    net10.0 agent (no UWP workload, no console): solution build + the
    //    Category=Xbox tests + the Native-AOT link of the ViceSharpXboxUwp=false
    //    fallback head. It may optionally be wired into CI.
    // Rollback for a bad sideload is documented in
    // docs/xbox/on-console-setup-runbook.md (WinAppDeployCmd uninstall + redeploy).

    AbsolutePath XboxHeadProject => RootDirectory / "src" / "ViceSharp.Xbox" / "ViceSharp.Xbox.csproj";

    AbsolutePath TestHarnessProject => RootDirectory / "tests" / "ViceSharp.TestHarness" / "ViceSharp.TestHarness.csproj";

    [Parameter("DeployXbox: the Dev-Mode console IP (or host:port) passed to WinAppDeployCmd -ip.")]
    readonly string XboxConsoleIp = null!;

    [Parameter("DeployXbox: the Dev-Mode pairing PIN passed to WinAppDeployCmd -pin.")]
    readonly string XboxPairingPin = null!;

    [Parameter("DeployXbox: override the MSIX to sideload. Default: the newest .msix under the ViceSharp.Xbox build output.")]
    readonly string XboxMsixPath = null!;

    /// <summary>
    /// DEV-PC / MANUAL (never CI): publish the <c>ViceSharp.Xbox</c>
    /// UWP-on-Xbox-console head as a Release Native-AOT MSIX (the Store publish
    /// path). Requires the windows-app / UWP workload
    /// (<c>ViceSharpXboxUwp=true</c> switches the head to the
    /// net10.0-windows UWP TFM); on a workload-less agent this target is simply
    /// not invoked (CI never calls it), while the definition still compiles.
    /// </summary>
    Target PublishXbox => _ => _
        .Description("DEV-PC/MANUAL (never CI): publish the ViceSharp.Xbox head as a Release Native-AOT MSIX. Requires the windows-app / UWP workload.")
        .Executes(() =>
        {
            Serilog.Log.Information(
                "Publishing the ViceSharp.Xbox UWP-on-console head (Release, Native AOT, win-x64, ViceSharpXboxUwp=true) -> MSIX. " +
                "This needs the windows-app / UWP workload; see docs/xbox/on-console-setup-runbook.md.");
            DotNetPublish(s => s
                .SetProject(XboxHeadProject)
                .SetConfiguration("Release")
                .SetRuntime("win-x64")
                .SetProperty("ViceSharpXboxUwp", "true")
                .SetProperty("PublishAot", "true"));
        });

    /// <summary>
    /// DEV-PC / MANUAL (never CI): sideload the packaged <c>ViceSharp.Xbox</c>
    /// MSIX to a paired Dev-Mode console with <c>WinAppDeployCmd</c>
    /// (<c>install -file &lt;msix&gt; -ip &lt;ip&gt; -pin &lt;pin&gt;</c>). Pass the
    /// console with <c>--xbox-console-ip</c>, the Dev-Mode PIN with
    /// <c>--xbox-pairing-pin</c>, and optionally an explicit MSIX with
    /// <c>--xbox-msix-path</c>. Rollback (a bad sideload) is documented in
    /// docs/xbox/on-console-setup-runbook.md: <c>WinAppDeployCmd uninstall</c> then
    /// redeploy the prior known-good MSIX (or the Device Portal Add-app fallback).
    /// </summary>
    Target DeployXbox => _ => _
        .Description("DEV-PC/MANUAL (never CI): sideload the ViceSharp.Xbox MSIX to a Dev-Mode console via WinAppDeployCmd. Params: --xbox-console-ip, --xbox-pairing-pin, [--xbox-msix-path].")
        .Requires(() => XboxConsoleIp)
        .Requires(() => XboxPairingPin)
        .Executes(() =>
        {
            var msix = ResolveXboxMsix();
            var winAppDeploy = FindOnPath("WinAppDeployCmd.exe") ?? FindOnPath("WinAppDeployCmd")
                ?? throw new InvalidOperationException(
                    "WinAppDeployCmd not found on PATH (it ships with the Windows 10/11 SDK). Install the "
                  + "SDK, or use the Device Portal Add-app sideload documented in "
                  + "docs/xbox/on-console-setup-runbook.md.");

            Serilog.Log.Information("Sideloading {Msix} to console {Ip} via WinAppDeployCmd install.", msix, XboxConsoleIp);
            RunProcess(winAppDeploy,
                $"install -file \"{msix}\" -ip {XboxConsoleIp} -pin {XboxPairingPin}",
                throwOnNonZero: true);
            Serilog.Log.Information(
                "Deployed {Msix} to {Ip}. To roll back: WinAppDeployCmd uninstall -package <PackageFullName> "
              + "-ip {Ip} -pin <pin>, then redeploy the prior MSIX (docs/xbox/on-console-setup-runbook.md).",
                msix, XboxConsoleIp, XboxConsoleIp);
        });

    /// <summary>
    /// OFF-CONSOLE, workload-free Xbox gate (safe on a plain net10.0 CI agent, no
    /// UWP workload, no console): (1) the whole solution builds (via
    /// <see cref="Compile"/>), (2) the <c>Category=Xbox</c> tests pass, and (3) the
    /// workload-free fallback head (<c>ViceSharpXboxUwp=false</c>, so the plain
    /// net10.0 TFM) links clean under Native AOT - proving the reused managed core +
    /// Host.InProcess graph is trim/AOT safe before any device slice. This is the CI-
    /// eligible half of the Xbox build; the DEVICE targets (PublishXbox/DeployXbox)
    /// stay manual.
    /// </summary>
    Target ValidateXbox => _ => _
        .Description("OFF-CONSOLE, workload-free Xbox gate (plain net10.0 agent): solution build + Category=Xbox tests + Native-AOT link of the ViceSharpXboxUwp=false fallback head.")
        .DependsOn(Compile)
        .Executes(() =>
        {
            // (1) Category=Xbox tests. Compile already built the solution in
            // Configuration, so run the harness assembly with no rebuild/restore.
            DotNetTest(s => s
                .SetProjectFile(TestHarnessProject)
                .SetConfiguration(Configuration)
                .SetNoRestore(true)
                .SetNoBuild(true)
                .SetFilter("Category=Xbox"));

            // (2) Native-AOT link of the workload-free fallback head. ViceSharpXboxUwp=false
            // keeps the plain net10.0 TFM (no UWP workload needed) while PublishAot=true
            // exercises the real trim/AOT link over the shipped core + Host.InProcess graph.
            DotNetPublish(s => s
                .SetProject(XboxHeadProject)
                .SetConfiguration("Release")
                .SetRuntime("win-x64")
                .SetProperty("ViceSharpXboxUwp", "false")
                .SetProperty("PublishAot", "true"));
        });

    /// <summary>
    /// Resolves the MSIX <see cref="DeployXbox"/> sideloads: the explicit
    /// <c>--xbox-msix-path</c> when given, else the newest <c>*.msix</c> under the
    /// ViceSharp.Xbox build output (PublishXbox produces it). Throws a directive to
    /// run PublishXbox / pass a path when none is found.
    /// </summary>
    AbsolutePath ResolveXboxMsix()
    {
        if (!string.IsNullOrWhiteSpace(XboxMsixPath))
        {
            var explicitPath = (AbsolutePath)XboxMsixPath;
            if (!System.IO.File.Exists(explicitPath))
                throw new InvalidOperationException($"--xbox-msix-path '{XboxMsixPath}' does not exist.");
            return explicitPath;
        }

        var searchRoot = XboxHeadProject.Parent / "bin";
        var newest = System.IO.Directory.Exists(searchRoot)
            ? searchRoot.GlobFiles("**/*.msix")
                .OrderByDescending(p => System.IO.File.GetLastWriteTimeUtc(p))
                .FirstOrDefault()
            : null;
        return newest
            ?? throw new InvalidOperationException(
                "No MSIX found under the ViceSharp.Xbox build output. Run PublishXbox first "
              + "(a dev PC with the windows-app / UWP workload), or pass --xbox-msix-path to a known-good MSIX.");
    }
}

