        set => SetSettingsProperty(ref _leftStickDeadzonePercent, Math.Clamp(value, 0, 90));
    }

    /// <summary>Right-stick radial deadzone as a percentage (Xbox-only pref).</summary>
    public double RightStickDeadzonePercent
