        Assert.True(romSet.IsComplete(provider));
        Assert.Equal(Vic20ViceRomNames.ArchitectureKey, romSet.Architecture);
    }

    [Fact]
    public void Vic20Descriptor_WithoutRomProvider_ThrowsClearError()
    {
