        Assert.NotNull(machine.Devices.GetByRole(DeviceRole.Cpu));
        Assert.NotNull(machine.Devices.GetByRole(DeviceRole.SystemRam));
        Assert.NotNull(machine.Devices.GetByRole(DeviceRole.VideoChip));
