                SwapJoystickPorts,
                ToInputModeId(SelectedInputMode)),
            GetSelectedMachineProfileId(),
            restartSession,
            new AudioSettingsDto(ToAudioModeId(SelectedAudioMode)),
            new ResourceSettingsDto(ToResourceModeId(SelectedResourceMode)));
