        // Field order mirrors struct vice_cia_state in native/vice-shim.h; the
        // trailing TR-LOCKSTEP-VSF-001 latch/mask fields are appended below.
        public ushort TimerA;
        public ushort TimerB;
        public byte Icr;
        public byte Cra;
        public byte Crb;
        public byte InterruptFlag;

