namespace ViceSharp.Chips.Cpu;

partial class Mos6502
{
    // Absolute,X read-modify-write opcodes (ASL/ROL/LSR/ROR/DEC/INC $nnnn,X:
    // 0x1E/0x3E/0x5E/0x7E/0xDE/0xFE) take 7 cycles: opcode, lo, hi, dummy read
    // at the un-fixed page, real read, RMW dummy write of the old value, write
    // (VICE 6510dtvcore.c INT_ABS_I_RMW; TR-LOCKSTEP-VSF-001).
    private static readonly byte[] OpCycleCounts = new byte[256]
    {
        /* 00 */ 7, 6, 2, 8, 3, 3, 5, 5, 3, 2, 2, 2, 4, 4, 6, 6,
        /* 10 */ 2, 5, 2, 8, 4, 4, 6, 6, 2, 4, 2, 7, 4, 4, 7, 7,
        /* 20 */ 6, 6, 2, 8, 3, 3, 5, 5, 4, 2, 2, 2, 4, 4, 6, 6,
        /* 30 */ 2, 5, 2, 8, 4, 4, 6, 6, 2, 4, 2, 7, 4, 4, 7, 7,
        /* 40 */ 6, 6, 2, 8, 3, 3, 5, 5, 3, 2, 2, 2, 3, 4, 6, 6,
        /* 50 */ 2, 5, 2, 8, 4, 4, 6, 6, 2, 4, 2, 7, 4, 4, 7, 7,
        /* 60 */ 6, 6, 2, 8, 3, 3, 5, 5, 4, 2, 2, 2, 5, 4, 6, 6,
        /* 70 */ 2, 5, 2, 8, 4, 4, 6, 6, 2, 4, 2, 7, 4, 4, 7, 7,
        /* 80 */ 2, 6, 2, 6, 3, 3, 3, 3, 2, 2, 2, 2, 4, 4, 4, 4,
        /* 90 */ 2, 6, 2, 6, 4, 4, 4, 4, 2, 5, 2, 5, 5, 5, 5, 5,
        /* A0 */ 2, 6, 2, 6, 3, 3, 3, 3, 2, 2, 2, 2, 4, 4, 4, 4,
        /* B0 */ 2, 5, 2, 5, 4, 4, 4, 4, 2, 4, 2, 4, 4, 4, 4, 4,
        /* C0 */ 2, 6, 2, 8, 3, 3, 5, 5, 2, 2, 2, 2, 4, 4, 6, 6,
        /* D0 */ 2, 5, 2, 8, 4, 4, 6, 6, 2, 4, 2, 7, 4, 4, 7, 7,
        /* E0 */ 2, 6, 2, 8, 3, 3, 5, 5, 2, 2, 2, 2, 4, 4, 6, 6,
        /* F0 */ 2, 5, 2, 8, 4, 4, 6, 6, 2, 4, 2, 7, 4, 4, 7, 7
    };

    private byte Fetch()
    {
        return _bus.Read(PC++);
    }

    private ushort FetchWord()
    {
        byte lo = Fetch();
        byte hi = Fetch();
        return (ushort)(lo | (hi << 8));
    }

    public int ExecuteInstruction()
    {
        byte opcode = Fetch();
        byte cycles = OpCycleCounts[opcode];

        ExecuteOpcode(opcode);

        return cycles;
    }

    private partial int GetCycleCount(byte opcode) => OpCycleCounts[opcode];

    private partial AddressingMode GetAddressingMode(byte opcode)
    {
        // Addressing mode lookup table implementation
        return (opcode & 0x03) switch
        {
            0 => (opcode & 0x18) switch
            {
                0x00 => AddressingMode.Immediate,
                0x08 => AddressingMode.ZeroPage,
                0x10 => AddressingMode.Absolute,
                0x18 => AddressingMode.Indirect,
                _ => AddressingMode.Implied
            },
            1 => (opcode & 0x10) switch
            {
                0x00 => AddressingMode.ZeroPageX,
                0x10 => AddressingMode.AbsoluteX,
                _ => AddressingMode.Implied
            },
            2 => (opcode & 0x10) switch
            {
                0x00 => AddressingMode.ZeroPageY,
                0x10 => AddressingMode.AbsoluteY,
                _ => AddressingMode.Implied
            },
            _ => AddressingMode.Implied
        };
    }

    private partial bool ExecuteAddressing(AddressingMode mode)
    {
        bool pageCrossed = false;

        switch (mode)
        {
            case AddressingMode.Immediate:
                _effectiveAddress = PC++;
                break;
            case AddressingMode.ZeroPage:
                _effectiveAddress = Fetch();
                break;
            case AddressingMode.ZeroPageX:
                _effectiveAddress = (byte)(Fetch() + X);
                break;
            case AddressingMode.ZeroPageY:
                _effectiveAddress = (byte)(Fetch() + Y);
                break;
            case AddressingMode.Absolute:
                _effectiveAddress = FetchWord();
                break;
            case AddressingMode.AbsoluteX:
                ushort baseAddr = FetchWord();
                _effectiveAddress = (ushort)(baseAddr + X);
                pageCrossed = (baseAddr & 0xFF00) != (_effectiveAddress & 0xFF00);
                break;
            case AddressingMode.AbsoluteY:
                baseAddr = FetchWord();
                _effectiveAddress = (ushort)(baseAddr + Y);
                pageCrossed = (baseAddr & 0xFF00) != (_effectiveAddress & 0xFF00);
                break;
            case AddressingMode.IndirectX:
                byte zpAddr = (byte)(Fetch() + X);
                _effectiveAddress = (ushort)(_bus.Read(zpAddr) | (_bus.Read((byte)(zpAddr + 1)) << 8));
                break;
            case AddressingMode.IndirectY:
                zpAddr = Fetch();
                baseAddr = (ushort)(_bus.Read(zpAddr) | (_bus.Read((byte)(zpAddr + 1)) << 8));
                _effectiveAddress = (ushort)(baseAddr + Y);
                pageCrossed = (baseAddr & 0xFF00) != (_effectiveAddress & 0xFF00);
                break;
            case AddressingMode.Relative:
                sbyte offset = (sbyte)Fetch();
                _effectiveAddress = (ushort)(PC + offset);
                break;
        }

        _fetched = _bus.Read(_effectiveAddress);
        return pageCrossed;
    }

    private partial bool IsPageBoundaryCycleRequired(byte opcode)
    {
        // Opcodes that require extra cycle on page boundary
        return (opcode & 0x0F) is 0x19 or 0x1D or 0x1E or 0x39 or 0x3D or 0x3E or 0x59 or 0x5D or 0x5E or 0x79 or 0x7D or 0x7E or 0xB1 or 0xB9 or 0xBD or 0xD1 or 0xD9 or 0xDD or 0xF1 or 0xF9 or 0xFD;
    }

    private partial void ExecuteOpcode(byte opcode)
    {
        switch (opcode)
        {
            // LDA - Load Accumulator
            case 0xA9: A = _bus.Read(Immediate()); UpdateNZ(A); break;
            case 0xA5: A = _bus.Read(ZeroPage()); UpdateNZ(A); break;
            case 0xB5: A = _bus.Read(ZeroPageX()); UpdateNZ(A); break;
            case 0xAD: A = _bus.Read(Absolute()); UpdateNZ(A); break;
            case 0xBD: A = _bus.Read(AbsoluteX()); UpdateNZ(A); break;
            case 0xB9: A = _bus.Read(AbsoluteY()); UpdateNZ(A); break;
            case 0xA1: A = _bus.Read(IndirectX()); UpdateNZ(A); break;
            case 0xB1: A = _bus.Read(IndirectY()); UpdateNZ(A); break;

            // LDX - Load X Register
            case 0xA2: X = _bus.Read(Immediate()); UpdateNZ(X); break;
            case 0xA6: X = _bus.Read(ZeroPage()); UpdateNZ(X); break;
            case 0xB6: X = _bus.Read(ZeroPageY()); UpdateNZ(X); break;
            case 0xAE: X = _bus.Read(Absolute()); UpdateNZ(X); break;
            case 0xBE: X = _bus.Read(AbsoluteY()); UpdateNZ(X); break;

            // LDY - Load Y Register
            case 0xA0: Y = _bus.Read(Immediate()); UpdateNZ(Y); break;
            case 0xA4: Y = _bus.Read(ZeroPage()); UpdateNZ(Y); break;
            case 0xB4: Y = _bus.Read(ZeroPageX()); UpdateNZ(Y); break;
            case 0xAC: Y = _bus.Read(Absolute()); UpdateNZ(Y); break;
            case 0xBC: Y = _bus.Read(AbsoluteX()); UpdateNZ(Y); break;

            // NOP - No Operation
            case 0xEA: break;

            // BRK - Force Interrupt
            // PC was already advanced past the opcode byte during fetch
            // (now PC = BRK+1). BRK also consumes the following signature
            // byte even though it is not read, so the stacked return
            // address is PC+1 (i.e. BRK+2). The pushed status byte has
            // the B flag (bit 4) set to distinguish BRK from a hardware
            // IRQ/NMI; the live P register gets the I flag set so the
            // handler runs with IRQs masked.
            case 0x00:
                PushWord((ushort)(PC + 1));
                Push((byte)(P | 0x10)); // Push P with B flag set (software interrupt)
                P |= 0x04; // Set Interrupt Disable flag
                PC = _bus.Read(0xFFFE);
                PC |= (ushort)(_bus.Read(0xFFFF) << 8);
                break;

            // RTI - Return from Interrupt
            case 0x40:
                P = Pop();
                PC = PopWord();
                break;

            // RTS - Return from Subroutine
            case 0x60:
                PC = PopWord();
                PC++;
                break;

            // JMP - Jump
            case 0x4C:
            {
                var source = (ushort)(PC - 1);
                var target = Absolute();
                PC = target;
                PublishControlTransfer(source, target, 0, opcode);
                break;
            }
            case 0x6C:
            {
                var source = (ushort)(PC - 1);
                var target = Indirect();
                PC = target;
                PublishControlTransfer(source, target, 0, opcode);
                break;
            }

            // JSR - Jump to Subroutine
            case 0x20:
                var jsrSource = (ushort)(PC - 1);
                ushort addr = Absolute();
                var returnPc = PC;
                PushWord((ushort)(PC - 1));
                PC = addr;
                PublishControlTransfer(jsrSource, addr, returnPc, opcode);
                break;

            // STA - Store Accumulator
            case 0x85: _bus.Write(ZeroPage(), A); break;
            case 0x95: _bus.Write(ZeroPageX(), A); break;
            case 0x8D: _bus.Write(Absolute(), A); break;
            case 0x9D: _bus.Write(AbsoluteX(), A); break;
            case 0x99: _bus.Write(AbsoluteY(), A); break;
            case 0x81: _bus.Write(IndirectX(), A); break;
            case 0x91: _bus.Write(IndirectY(), A); break;

            // STX - Store X Register
            case 0x86: _bus.Write(ZeroPage(), X); break;
            case 0x96: _bus.Write(ZeroPageY(), X); break;
            case 0x8E:
                var stxAddress = Absolute();
                _bus.Write(stxAddress, X);
                DelayNextFetchAfterMappedIoWrite(stxAddress);
                break;

            // STY - Store Y Register
            case 0x84: _bus.Write(ZeroPage(), Y); break;
            case 0x94: _bus.Write(ZeroPageX(), Y); break;
            case 0x8C: _bus.Write(Absolute(), Y); break;

            // TAX - Transfer Accumulator to X
            case 0xAA: X = A; UpdateNZ(X); break;

            // TAY - Transfer Accumulator to Y
            case 0xA8: Y = A; UpdateNZ(Y); break;

            // TXA - Transfer X to Accumulator
            case 0x8A: A = X; UpdateNZ(A); break;

            // TYA - Transfer Y to Accumulator
            case 0x98: A = Y; UpdateNZ(A); break;

            // TXS - Transfer X to Stack Pointer
            case 0x9A: S = X; break;

            // TSX - Transfer Stack Pointer to X
            case 0xBA: X = S; UpdateNZ(X); break;

            // INX - Increment X Register
            case 0xE8: X++; UpdateNZ(X); break;

            // INY - Increment Y Register
            case 0xC8: Y++; UpdateNZ(Y); break;

            // DEX - Decrement X Register
            case 0xCA: X--; UpdateNZ(X); break;

            // DEY - Decrement Y Register
            case 0x88: Y--; UpdateNZ(Y); break;

            // CLC - Clear Carry Flag
            case 0x18: P &= 0xFE; break;

            // SEC - Set Carry Flag
            case 0x38: P |= 0x01; break;

            // CLI - Clear Interrupt Disable
            case 0x58: P &= 0xFB; break;

            // SEI - Set Interrupt Disable
            case 0x78: P |= 0x04; break;

            // CLV - Clear Overflow Flag
            case 0xB8: P &= 0xBF; break;

            // SED - Set Decimal Flag
            case 0xF8: P |= 0x08; break;

            // CLD - Clear Decimal Flag
            case 0xD8: P &= 0xF7; break;

            // PHA - Push Accumulator
            case 0x48: Push(A); break;

            // PHP - Push Processor Status
            case 0x08: Push((byte)(P | 0x10)); break;

            // PLA - Pull Accumulator
            case 0x68: A = Pop(); UpdateNZ(A); break;

            // PLP - Pull Processor Status
            case 0x28: P = (byte)((Pop() & ~0x10) | (P & 0x10)); break;

            // BIT - Bit Test
            case 0x24:
                byte value = _bus.Read(ZeroPage());
                P &= 0x3D;
                P |= (byte)(value & 0xC0);
                if ((A & value) == 0) P |= 0x02;
                break;
            case 0x2C:
                value = _bus.Read(Absolute());
                P &= 0x3D;
                P |= (byte)(value & 0xC0);
                if ((A & value) == 0) P |= 0x02;
                break;

            // NOP undocumented variants
            case 0x1A:
            case 0x3A:
            case 0x5A:
            case 0x7A:
            case 0xDA:
            case 0xFA:
                break;

            // INC - Increment Memory
            case 0xE6:
                _effectiveAddress = ZeroPage();
                value = _bus.Read(_effectiveAddress);
                value++;
                _bus.Write(_effectiveAddress, value);
                UpdateNZ(value);
                break;
            case 0xF6:
                _effectiveAddress = ZeroPageX();
                value = _bus.Read(_effectiveAddress);
                value++;
                _bus.Write(_effectiveAddress, value);
                UpdateNZ(value);
                break;
            case 0xEE:
                _effectiveAddress = Absolute();
                value = _bus.Read(_effectiveAddress);
                value++;
                _bus.Write(_effectiveAddress, value);
                UpdateNZ(value);
                break;
            case 0xFE:
                _effectiveAddress = AbsoluteX();
                value = _bus.Read(_effectiveAddress);
                value++;
                _bus.Write(_effectiveAddress, value);
                UpdateNZ(value);
                break;

            // DEC - Decrement Memory
            case 0xC6:
                _effectiveAddress = ZeroPage();
                value = _bus.Read(_effectiveAddress);
                value--;
                _bus.Write(_effectiveAddress, value);
                UpdateNZ(value);
                break;
            case 0xD6:
                _effectiveAddress = ZeroPageX();
                value = _bus.Read(_effectiveAddress);
                value--;
                _bus.Write(_effectiveAddress, value);
                UpdateNZ(value);
                break;
            case 0xCE:
                _effectiveAddress = Absolute();
                value = _bus.Read(_effectiveAddress);
                value--;
                _bus.Write(_effectiveAddress, value);
                UpdateNZ(value);
                break;
            case 0xDE:
                _effectiveAddress = AbsoluteX();
                value = _bus.Read(_effectiveAddress);
                value--;
                _bus.Write(_effectiveAddress, value);
                UpdateNZ(value);
                break;

            // CMP - Compare Accumulator
            case 0xC9: Compare(A, Immediate()); break;
            case 0xC5: Compare(A, ZeroPage()); break;
            case 0xD5: Compare(A, ZeroPageX()); break;
            case 0xCD: Compare(A, Absolute()); break;
            case 0xDD: Compare(A, AbsoluteX()); break;
            case 0xD9: Compare(A, AbsoluteY()); break;
            case 0xC1: Compare(A, IndirectX()); break;
            case 0xD1: Compare(A, IndirectY()); break;

            // CPX - Compare X Register
            case 0xE0: Compare(X, Immediate()); break;
            case 0xE4: Compare(X, ZeroPage()); break;
            case 0xEC: Compare(X, Absolute()); break;

            // CPY - Compare Y Register
            case 0xC0: Compare(Y, Immediate()); break;
            case 0xC4: Compare(Y, ZeroPage()); break;
            case 0xCC: Compare(Y, Absolute()); break;

            // Branch Instructions
            case 0x10: BranchRelative((P & 0x80) == 0); break; // BPL
            case 0x30: BranchRelative((P & 0x80) != 0); break; // BMI
            case 0x50: BranchRelative((P & 0x40) == 0); break; // BVC
            case 0x70: BranchRelative((P & 0x40) != 0); break; // BVS
            case 0x90: BranchRelative((P & 0x01) == 0); break; // BCC
            case 0xB0: BranchRelative((P & 0x01) != 0); break; // BCS
            case 0xD0: BranchRelative((P & 0x02) == 0); break; // BNE
            case 0xF0: BranchRelative((P & 0x02) != 0); break; // BEQ

            // Logical AND
            case 0x29: A &= _bus.Read(Immediate()); UpdateNZ(A); break;
            case 0x25: A &= _bus.Read(ZeroPage()); UpdateNZ(A); break;
            case 0x35: A &= _bus.Read(ZeroPageX()); UpdateNZ(A); break;
            case 0x2D: A &= _bus.Read(Absolute()); UpdateNZ(A); break;
            case 0x3D: A &= _bus.Read(AbsoluteX()); UpdateNZ(A); break;
            case 0x39: A &= _bus.Read(AbsoluteY()); UpdateNZ(A); break;
            case 0x21: A &= _bus.Read(IndirectX()); UpdateNZ(A); break;
            case 0x31: A &= _bus.Read(IndirectY()); UpdateNZ(A); break;

            // Logical OR
            case 0x09: A |= _bus.Read(Immediate()); UpdateNZ(A); break;
            case 0x05: A |= _bus.Read(ZeroPage()); UpdateNZ(A); break;
            case 0x15: A |= _bus.Read(ZeroPageX()); UpdateNZ(A); break;
            case 0x0D: A |= _bus.Read(Absolute()); UpdateNZ(A); break;
            case 0x1D: A |= _bus.Read(AbsoluteX()); UpdateNZ(A); break;
            case 0x19: A |= _bus.Read(AbsoluteY()); UpdateNZ(A); break;
            case 0x01: A |= _bus.Read(IndirectX()); UpdateNZ(A); break;
            case 0x11: A |= _bus.Read(IndirectY()); UpdateNZ(A); break;

            // Logical Exclusive OR
            case 0x49: A ^= _bus.Read(Immediate()); UpdateNZ(A); break;
            case 0x45: A ^= _bus.Read(ZeroPage()); UpdateNZ(A); break;
            case 0x55: A ^= _bus.Read(ZeroPageX()); UpdateNZ(A); break;
            case 0x4D: A ^= _bus.Read(Absolute()); UpdateNZ(A); break;
            case 0x5D: A ^= _bus.Read(AbsoluteX()); UpdateNZ(A); break;
            case 0x59: A ^= _bus.Read(AbsoluteY()); UpdateNZ(A); break;
            case 0x41: A ^= _bus.Read(IndirectX()); UpdateNZ(A); break;
            case 0x51: A ^= _bus.Read(IndirectY()); UpdateNZ(A); break;

            // Arithmetic Shift Left
            case 0x0A: A = ASL(A); break;
            case 0x06:
                _effectiveAddress = ZeroPage();
                _bus.Write(_effectiveAddress, ASL(_bus.Read(_effectiveAddress)));
                break;
            case 0x16:
                _effectiveAddress = ZeroPageX();
                _bus.Write(_effectiveAddress, ASL(_bus.Read(_effectiveAddress)));
                break;
            case 0x0E:
                _effectiveAddress = Absolute();
                _bus.Write(_effectiveAddress, ASL(_bus.Read(_effectiveAddress)));
                break;
            case 0x1E:
                _effectiveAddress = AbsoluteX();
                _bus.Write(_effectiveAddress, ASL(_bus.Read(_effectiveAddress)));
                break;

            // Logical Shift Right
            case 0x4A: A = LSR(A); break;
            case 0x46:
                _effectiveAddress = ZeroPage();
                _bus.Write(_effectiveAddress, LSR(_bus.Read(_effectiveAddress)));
                break;
            case 0x56:
                _effectiveAddress = ZeroPageX();
                _bus.Write(_effectiveAddress, LSR(_bus.Read(_effectiveAddress)));
                break;
            case 0x4E:
                _effectiveAddress = Absolute();
                _bus.Write(_effectiveAddress, LSR(_bus.Read(_effectiveAddress)));
                break;
            case 0x5E:
                _effectiveAddress = AbsoluteX();
                _bus.Write(_effectiveAddress, LSR(_bus.Read(_effectiveAddress)));
                break;

            // Rotate Left
            case 0x2A: A = ROL(A); break;
            case 0x26:
                _effectiveAddress = ZeroPage();
                _bus.Write(_effectiveAddress, ROL(_bus.Read(_effectiveAddress)));
                break;
            case 0x36:
                _effectiveAddress = ZeroPageX();
                _bus.Write(_effectiveAddress, ROL(_bus.Read(_effectiveAddress)));
                break;
            case 0x2E:
                _effectiveAddress = Absolute();
                _bus.Write(_effectiveAddress, ROL(_bus.Read(_effectiveAddress)));
                break;
            case 0x3E:
                _effectiveAddress = AbsoluteX();
                _bus.Write(_effectiveAddress, ROL(_bus.Read(_effectiveAddress)));
                break;

            // Rotate Right
            case 0x6A: A = ROR(A); break;
            case 0x66:
                _effectiveAddress = ZeroPage();
                _bus.Write(_effectiveAddress, ROR(_bus.Read(_effectiveAddress)));
                break;
            case 0x76:
                _effectiveAddress = ZeroPageX();
                _bus.Write(_effectiveAddress, ROR(_bus.Read(_effectiveAddress)));
                break;
            case 0x6E:
                _effectiveAddress = Absolute();
                _bus.Write(_effectiveAddress, ROR(_bus.Read(_effectiveAddress)));
                break;
            case 0x7E:
                _effectiveAddress = AbsoluteX();
                _bus.Write(_effectiveAddress, ROR(_bus.Read(_effectiveAddress)));
                break;

            // ADC - Add with Carry
            case 0x69: ADC(_bus.Read(Immediate())); break;
            case 0x65: ADC(_bus.Read(ZeroPage())); break;
            case 0x75: ADC(_bus.Read(ZeroPageX())); break;
            case 0x6D: ADC(_bus.Read(Absolute())); break;
            case 0x7D: ADC(_bus.Read(AbsoluteX())); break;
            case 0x79: ADC(_bus.Read(AbsoluteY())); break;
            case 0x61: ADC(_bus.Read(IndirectX())); break;
            case 0x71: ADC(_bus.Read(IndirectY())); break;

            // SBC - Subtract with Carry
            case 0xE9: SBC(_bus.Read(Immediate())); break;
            case 0xE5: SBC(_bus.Read(ZeroPage())); break;
            case 0xF5: SBC(_bus.Read(ZeroPageX())); break;
            case 0xED: SBC(_bus.Read(Absolute())); break;
            case 0xFD: SBC(_bus.Read(AbsoluteX())); break;
            case 0xF9: SBC(_bus.Read(AbsoluteY())); break;
            case 0xE1: SBC(_bus.Read(IndirectX())); break;
            case 0xF1: SBC(_bus.Read(IndirectY())); break;

            // KIL (CPU freeze)
            case 0x02: case 0x12: case 0x22: case 0x32: case 0x42: case 0x52: case 0x62: case 0x72:
            case 0x92: case 0xB2: case 0xD2: case 0xF2: break;

            // LAX (load A and X)
            case 0xAB: A = X = _bus.Read(Immediate()); UpdateNZ(A); break;
            case 0xA7: A = X = _bus.Read(ZeroPage()); UpdateNZ(A); break;
            case 0xB7: A = X = _bus.Read(ZeroPageY()); UpdateNZ(A); break;
            case 0xAF: A = X = _bus.Read(Absolute()); UpdateNZ(A); break;
            case 0xBF: A = X = _bus.Read(AbsoluteY()); UpdateNZ(A); break;
            case 0xA3: A = X = _bus.Read(IndirectX()); UpdateNZ(A); break;
            case 0xB3: A = X = _bus.Read(IndirectY()); UpdateNZ(A); break;

            // SAX (store A AND X)
            case 0x87: _bus.Write(ZeroPage(), (byte)(A & X)); break;
            case 0x97: _bus.Write(ZeroPageY(), (byte)(A & X)); break;
            case 0x8F: _bus.Write(Absolute(), (byte)(A & X)); break;
            case 0x83: _bus.Write(IndirectX(), (byte)(A & X)); break;

            default:
                // Unimplemented opcode - read to consume cycle
                break;
        }
    }

    private void UpdateNZ(byte value)
    {
        P = (byte)(P & ~(0x02 | 0x80));
        if (value == 0) P |= 0x02;
        if ((value & 0x80) != 0) P |= 0x80;
    }

    private void SetFlag(byte mask)
    {
        P |= mask;
    }

    private void ClearFlag(byte mask)
    {
        P = (byte)(P & ~mask);
    }

    private void Push(byte value)
    {
        _bus.Write((ushort)(0x0100 + S--), value);
    }

    private byte Pop()
    {
        return _bus.Read((ushort)(0x0100 + ++S));
    }

    private void PushWord(ushort value)
    {
        Push((byte)(value >> 8));
        Push((byte)value);
    }

    private ushort PopWord()
    {
        byte lo = Pop();
        byte hi = Pop();
        return (ushort)(lo | (hi << 8));
    }

    private void Compare(byte register, ushort address)
    {
        byte value = _bus.Read(address);
        ushort result = (ushort)(register - value);

        if (register >= value)
            P |= 0x01;
        else
            P &= 0xFE;

        UpdateNZ((byte)result);
    }

    private void BranchRelative(bool shouldBranch)
    {
        sbyte offset = (sbyte)Fetch();
        if (shouldBranch)
            PC = (ushort)(PC + offset);
    }

    private byte ASL(byte value)
    {
        if ((value & 0x80) != 0)
            P |= 0x01;
        else
            P &= 0xFE;

        value <<= 1;
        UpdateNZ(value);
        return value;
    }

    private byte LSR(byte value)
    {
        if ((value & 0x01) != 0)
            P |= 0x01;
        else
            P &= 0xFE;

        value >>= 1;
        UpdateNZ(value);
        return value;
    }

    private byte ROL(byte value)
    {
        byte carry = (byte)(P & 0x01);

        if ((value & 0x80) != 0)
            P |= 0x01;
        else
            P &= 0xFE;

        value = (byte)((value << 1) | carry);
        UpdateNZ(value);
        return value;
    }

    private byte ROR(byte value)
    {
        byte carry = (byte)((P & 0x01) << 7);

        if ((value & 0x01) != 0)
            P |= 0x01;
        else
            P &= 0xFE;

        value = (byte)((value >> 1) | carry);
        UpdateNZ(value);
        return value;
    }

    private void ADC(byte value)
    {
        int carry = (P & 0x01);
        int result = A + value + carry;

        // Overflow flag
        if (((A ^ result) & (value ^ result) & 0x80) != 0)
            P |= 0x40;
        else
            P &= 0xBF;

        // Carry flag
        if (result > 0xFF)
            P |= 0x01;
        else
            P &= 0xFE;

        A = (byte)result;
        UpdateNZ(A);
    }

    private void SBC(byte value)
    {
        int carry = (P & 0x01) ^ 0x01;
        int result = A - value - carry;

        // Overflow flag
        if (((A ^ result) & (~value ^ result) & 0x80) != 0)
            P |= 0x40;
        else
            P &= 0xBF;

        // Carry flag
        if (result >= 0)
            P |= 0x01;
        else
            P &= 0xFE;

        A = (byte)result;
        UpdateNZ(A);
    }
}

