            0x69 or 0x65 or 0x75 or 0x6D or 0x7D or 0x79 or 0x61 or 0x71 or
            0xE9 or 0xE5 or 0xF5 or 0xED or 0xFD or 0xF9 or 0xE1 or 0xF1 or
            0xE6 or 0xF6 or 0xEE or 0xFE or
            0xC6 or 0xD6 or 0xCE or 0xDE or
