            // CLK (VICE INC_PC after last FETCH). Sticks across consecutive NOPs
            // so the second padding NOP after the branch also matches (c=518741).
            if (_opcode == 0xEA && (armAfterBranchLag || _nopChainHoldAfterBranch))
