            _indexedLoadPageCrossDelayConsumed = false;
            _stagedReturnAddress = 0;
            _effectiveAddress = 0;
            _fetched = 0;

        }

        _cycle--;

        if (TryExecuteCycleStagedOpcode())
        {
            return;
        }

        if (TryDeferImpliedRegisterCompletionAfterBranch())
        {
            return;
        }

