                    || ((_previousOpcode is 0x48 or 0x08)
                        && DebugPriorTrailingAtNextPc == 1)
                    || (_afterFullLengthTakenBranch
                        && DebugPriorTrailingAtNextPc >= 2)
                    || _fuseImpliedAfterIndyLoad))
