            // (CMP#/AND#/etc.) so final FETCH sample keeps opcode PC; commit at
            // the next instruction's first tick (VICE INC_PC after last FETCH).
            if (_softDeferAfterNopChain && IsTwoByteImmediateOpcode(_opcode))
            {
