                _softDeferredImpliedOpcode = _opcode;
                _softDeferredImpliedInstructionPc = _opcodeAddress;
                _softDeferAfterNopChain = false;
                _visiblePC = _opcodeAddress;
                _suppressBootstrapBoundary = true;
                return;
            }

