            // so SystemClock does not sample IRQ one CLK early vs VICE after the
            // RMW final sample (c=540734 nS=$F5 mS=$F4 on first IRQ push).
            if (_zpRmwModifyCommitted && IsZeroPageShiftRmwOpcode(_opcode))
            {
