        // NTSC KERNAL-style origin (common $9000=5, $9001=25); geometry sizes do not depend on it.
        machine.Bus.Write(0x9000, 5);
        machine.Bus.Write(0x9001, 25);
        machine.Bus.Write(0x9002, unchecked((byte)(22 | 0x80)));
