        get => _expansionCart.WriteBack;
        set
        {
            if (_expansionCart.WriteBack == value)
                return;
            _expansionCart.WriteBack = value;
            OnPropertyChanged();
            if (!_suppressTracking)
                RecomputeDirtyState();
