    DeviceSetup,

    /// <summary>The input-mapping page: view and rebind the controller bindings.</summary>
    InputMapping,

    /// <summary>The about page: GPL-2.0-or-later disclosure, VICE attribution, and source offer.</summary>
    About,

    /// <summary>
